using MyPiggyBank.Core;
using System.Text.Json;

internal static class BorrowTransferChecks
{
    private static readonly DateOnly Start=new(2026,10,1);
    private static readonly Bank Bca=new(Guid.NewGuid(),"BCA",Start,3_000_000),Ocbc=new(Guid.NewGuid(),"OCBC",Start,2_000_000);
    private static readonly Category Income=new(Guid.NewGuid(),"Salary",CategoryKind.Income),Expense=new(Guid.NewGuid(),"Shopping",CategoryKind.Expense);
    private static readonly Purpose Pocket=new(Guid.NewGuid(),"Pocket money"),Savings=new(Guid.NewGuid(),"Savings");
    private static readonly Guid Id=Guid.NewGuid();
    private static Debt Loan()=>new(Id,"Pocket money","",null,Kind:DebtKind.Self,SelfBankId:Ocbc.Id);
    private static FinanceDocument Empty()=>new(){Banks=[Bca,Ocbc],Categories=[Income,Expense],Purposes=[Pocket,Savings]};
    private static Transaction Borrow(decimal amount=500_000)=>new(Guid.NewGuid(),new(2026,10,4),TransactionKind.Transfer,Ocbc.Id,Bca.Id,null,amount,2500,null,"Pocket money",[new(Pocket.Id,amount,Id,SelfDebtAction.Borrow)]);
    private static Transaction Repay(decimal amount=200_000)=>new(Guid.NewGuid(),new(2026,10,10),TransactionKind.Transfer,Bca.Id,Ocbc.Id,null,amount,2500,null,"Return pocket money",[new(Pocket.Id,amount,Id)]);
    private static FinanceDocument Ready()=>DebtService.SaveTransaction(Empty(),Borrow(),Loan());
    private static FinanceDocument Partial()=>DebtService.SaveTransaction(Ready(),Repay());
    private static void Equal<T>(T expected,T actual){if(!EqualityComparer<T>.Default.Equals(expected,actual))throw new Exception($"Expected {expected}, got {actual}");}
    private static void Reject(Action action){try{action();}catch(InvalidDataException){return;}throw new Exception("Expected rejection");}
    public static FinanceDocument Fixture()
    {
        var d=Partial();d.Transactions.Add(Borrow(100_000) with{Date=new(2026,10,2),Description="Old transfer to track",Allocations=null});d.Validate();return d;
    }
    public static void Run(Action<string,Action> test)
    {
        test("borrowing transfer creates Self Debt without Income or Expense principal",()=>{var d=Ready();Equal(new DebtTotals(500_000,0),d.DebtAmounts(Id));Equal(1,d.Transactions.Count);Equal(1_497_500m,d.Balance(Ocbc.Id));Equal(3_500_000m,d.Balance(Bca.Id));Equal((0m,2500m),d.Totals(Start,new(2026,10,31)));Equal(DebtStatus.Open,d.DebtState(Id));});
        test("tagging a historical transfer leaves cash reports and ID unchanged",()=>{var d=Empty();var tx=Borrow() with{Allocations=[new(Pocket.Id,500_000)]};d.Transactions.Add(tx);var cash=d.Banks.Select(b=>d.Balance(b.Id)).ToArray();var report=d.Totals(Start,new(2026,10,31));d=DebtService.SaveTransaction(d,tx with{Allocations=[new(Pocket.Id,500_000,Id,SelfDebtAction.Borrow)]},Loan());Equal(tx.Id,d.Transactions.Single().Id);Equal(1,d.Transactions.Count);Equal(true,cash.SequenceEqual(d.Banks.Select(b=>d.Balance(b.Id))));Equal(report,d.Totals(Start,new(2026,10,31)));});
        test("split borrowing uses only the linked purpose amount",()=>{var tx=Borrow(1_000_000) with{Allocations=[new(Pocket.Id,500_000,Id,SelfDebtAction.Borrow),new(Savings.Id,500_000)]};var d=DebtService.SaveTransaction(Empty(),tx,Loan());Equal(500_000m,d.DebtAmounts(Id).Remaining);Equal(4_000_000m,d.Balance(Bca.Id));Equal(true,d.AllocationSummary(tx).Contains("Borrow:"));});
        test("borrowing transfer fees never increase principal",()=>{var d=DebtService.SaveTransaction(Empty(),Borrow() with{Fee=25_000},Loan());Equal(500_000m,d.DebtAmounts(Id).Borrowed);Equal(1_475_000m,d.Balance(Ocbc.Id));});
        test("repayment returns to the source and reduces only marked principal",()=>{var d=Partial();Equal(new DebtTotals(500_000,200_000),d.DebtAmounts(Id));Equal(1_697_500m,d.Balance(Ocbc.Id));Equal(3_297_500m,d.Balance(Bca.Id));Equal((0m,5000m),d.Totals(Start,new(2026,10,31)));Equal(DebtStatus.PartiallyPaid,d.DebtState(Id));});
        test("unmarked reverse transfer is not an automatic repayment",()=>{var d=DebtService.SaveTransaction(Ready(),Repay() with{Allocations=null});Equal(0m,d.DebtAmounts(Id).Paid);});
        test("additional borrowing preserves the same original account",()=>{var d=DebtService.SaveTransaction(Partial(),Borrow(300_000) with{Date=new(2026,10,15)});Equal(new DebtTotals(800_000,200_000),d.DebtAmounts(Id));Equal(1,d.Debts.Count);});
        test("borrowing from another bank is rejected",()=>Reject(()=>DebtService.SaveTransaction(Ready(),Borrow() with{BankId=Bca.Id,ToBankId=Ocbc.Id})));
        test("repayment to the wrong original bank is rejected",()=>Reject(()=>DebtService.SaveTransaction(Ready(),Repay() with{BankId=Ocbc.Id,ToBankId=Bca.Id})));
        test("changing Borrow into Repay cannot silently reverse debt meaning",()=>{var d=Ready();var tx=d.Transactions.Single();Reject(()=>DebtService.SaveTransaction(d,tx with{Allocations=[new(Pocket.Id,500_000,Id)]}));});
        test("Borrow allocation needs an explicit valid link and action",()=>{Reject(()=>DebtService.SaveTransaction(Empty(),Borrow() with{Allocations=[new(Pocket.Id,500_000,null,SelfDebtAction.Borrow)]}));Reject(()=>DebtService.SaveTransaction(Empty(),Borrow() with{Allocations=[new(Pocket.Id,500_000,Guid.NewGuid(),SelfDebtAction.Borrow)]}));Reject(()=>DebtService.SaveTransaction(Empty(),Borrow() with{Allocations=[new(Pocket.Id,500_000,Id,(SelfDebtAction)99)]},Loan()));});
        test("borrowing transfer cannot create an external lender debt",()=>Reject(()=>DebtService.SaveTransaction(Empty(),Borrow(),new(Id,"Loan","Alex",null))));
        test("new metadata needs a matching borrowing origin",()=>{Reject(()=>DebtService.SaveTransaction(Empty(),Borrow() with{Allocations=null},Loan()));Reject(()=>DebtService.SaveTransaction(Empty(),Repay(),Loan()));});
        test("multiple new debts commit with one split transfer atomically",()=>{var other=Loan() with{Id=Guid.NewGuid(),Name="Other purpose"};var tx=Borrow() with{Allocations=[new(Pocket.Id,300_000,Id,SelfDebtAction.Borrow),new(Pocket.Id,200_000,other.Id,SelfDebtAction.Borrow)]};var source=Empty();var d=DebtService.SaveTransaction(source,tx,additionalDebts:[Loan(),other]);Equal(2,d.Debts.Count);Equal(1,d.Transactions.Count);Equal(300_000m,d.DebtAmounts(Id).Remaining);Equal(200_000m,d.DebtAmounts(other.Id).Remaining);Equal(0,source.Debts.Count);Equal(0,source.Transactions.Count);});
        test("failed multiple-debt transfer leaves no new metadata",()=>{var source=Empty();var before=JsonSerializer.Serialize(source);var other=Loan() with{Id=Guid.NewGuid(),Name=""};var tx=Borrow() with{Allocations=[new(Pocket.Id,300_000,Id,SelfDebtAction.Borrow),new(Savings.Id,200_000,other.Id,SelfDebtAction.Borrow)]};Reject(()=>DebtService.SaveTransaction(source,tx,additionalDebts:[Loan(),other]));Equal(before,JsonSerializer.Serialize(source));});
        test("same debt borrowing rows aggregate once in transaction history",()=>{var d=DebtService.SaveTransaction(Empty(),Borrow() with{Allocations=[new(Pocket.Id,300_000,Id,SelfDebtAction.Borrow),new(Savings.Id,200_000,Id,SelfDebtAction.Borrow)]},Loan());Equal(1,d.DebtEntries(Id).Count());Equal(500_000m,d.DebtEntries(Id).Single().Amount);Equal(true,d.DebtEntries(Id).Single().AddsPrincipal);});
        test("duplicate purpose debt action combinations are rejected",()=>Reject(()=>DebtService.SaveTransaction(Empty(),Borrow() with{Allocations=[new(Pocket.Id,250_000,Id,SelfDebtAction.Borrow),new(Pocket.Id,250_000,Id,SelfDebtAction.Borrow)]},Loan())));
        test("payments cannot precede the borrowing transfer",()=>Reject(()=>DebtService.SaveTransaction(Ready(),Repay() with{Date=new(2026,10,3)})));
        test("borrowing date and amount edits validate later payments",()=>{var d=Partial();var tx=d.Transactions.First();Reject(()=>DebtService.SaveTransaction(d,tx with{Date=new(2026,10,11)}));Reject(()=>DebtService.SaveTransaction(d,tx with{Amount=100_000,Allocations=[new(Pocket.Id,100_000,Id,SelfDebtAction.Borrow)]}));});
        test("deleting a transfer top-up validates later repayment history",()=>{var d=DebtService.SaveTransaction(Ready(),Borrow(300_000) with{Date=new(2026,10,5)});d=DebtService.SaveTransaction(d,Repay(700_000));var copy=d.Copy();copy.Transactions.RemoveAt(1);Reject(copy.Validate);});
        test("removing the last borrowing link requires Remove Tracking",()=>{var d=Ready();var tx=d.Transactions.Single();Reject(()=>DebtService.SaveTransaction(d,tx with{Allocations=[new(Pocket.Id,500_000)]}));d.Transactions.Clear();Reject(d.Validate);});
        test("Paid transfer debt must reopen before additional borrowing",()=>{var d=DebtService.SaveTransaction(Ready(),Repay(500_000));Equal(DebtStatus.PendingConfirmation,d.DebtState(Id));d=DebtService.SetPaid(d,Id,true);var tx=Borrow(50_000) with{Date=new(2026,10,15)};Reject(()=>DebtService.SaveTransaction(d,tx));d=DebtService.SetPaid(d,Id,false);d=DebtService.SaveTransaction(d,tx);Equal(50_000m,d.DebtAmounts(Id).Remaining);});
        test("Income can repay a transfer-origin Self Debt",()=>{var tx=new Transaction(Guid.NewGuid(),new(2026,10,10),TransactionKind.Income,Ocbc.Id,null,Income.Id,300_000,2500,null,"Income",SelfDebtPayment:new(Id,200_000));var d=DebtService.SaveTransaction(Ready(),tx);Equal(300_000m,d.DebtAmounts(Id).Remaining);Equal(1_795_000m,d.Balance(Ocbc.Id));});
        test("ordinary spending from destination does not add debt again",()=>{var tx=new Transaction(Guid.NewGuid(),new(2026,10,6),TransactionKind.Expense,Bca.Id,null,Expense.Id,100_000,0,null,"Pocket spending");var d=DebtService.SaveTransaction(Ready(),tx);Equal(500_000m,d.DebtAmounts(Id).Borrowed);Equal(3_400_000m,d.Balance(Bca.Id));});
        test("one transfer can borrow and repay different account debts through distinct rows",()=>{var other=Loan() with{Id=Guid.NewGuid(),Name="BCA funds",SelfBankId=Bca.Id};var expense=new Transaction(Guid.NewGuid(),new(2026,10,2),TransactionKind.Expense,Bca.Id,null,Expense.Id,500_000,0,null,"Original",DebtId:other.Id);var d=DebtService.SaveTransaction(Empty(),expense,other);var tx=Borrow() with{Allocations=[new(Pocket.Id,200_000,Id,SelfDebtAction.Borrow),new(Savings.Id,300_000,other.Id)]};d=DebtService.SaveTransaction(d,tx,Loan());Equal(200_000m,d.DebtAmounts(Id).Remaining);Equal(200_000m,d.DebtAmounts(other.Id).Remaining);});
        test("same transfer cannot borrow and repay the same account debt",()=>Reject(()=>DebtService.SaveTransaction(Empty(),Borrow() with{Allocations=[new(Pocket.Id,250_000,Id,SelfDebtAction.Borrow),new(Savings.Id,250_000,Id)]},Loan())));
        test("Remove Tracking keeps borrowing cash and purpose totals",()=>{var d=Partial();var cash=d.Banks.Select(b=>d.Balance(b.Id)).ToArray();var report=d.Totals(Start,new(2026,10,31));d=DebtService.RemoveTracking(d,Id);Equal(0,d.Debts.Count);Equal(2,d.Transactions.Count);Equal(true,cash.SequenceEqual(d.Banks.Select(b=>d.Balance(b.Id))));Equal(report,d.Totals(Start,new(2026,10,31)));Equal(true,d.Transactions.SelectMany(t=>t.Allocations??[]).All(a=>a.SelfDebtId is null&&a.DebtAction==SelfDebtAction.Repay));Equal(500_000m,d.Transactions.First().Allocations!.Single().Amount);});
        test("removing multiple debts with the same purpose merges detached notes safely",()=>{var other=Loan() with{Id=Guid.NewGuid(),Name="Second"};var d=DebtService.SaveTransaction(Empty(),Borrow() with{Allocations=[new(Pocket.Id,300_000,Id,SelfDebtAction.Borrow),new(Pocket.Id,200_000,other.Id,SelfDebtAction.Borrow)]},additionalDebts:[Loan(),other]);d=DebtService.RemoveTracking(d,Id);d=DebtService.RemoveTracking(d,other.Id);Equal(0,d.Debts.Count);Equal(500_000m,d.Transactions.Single().Allocations!.Single().Amount);});
        test("future borrowing transfers are rejected",()=>Reject(()=>DebtService.SaveTransaction(Empty(),Borrow() with{Date=DateOnly.FromDateTime(DateTime.Today).AddDays(1)},Loan())));
        test("format eight cannot silently interpret Borrow as Repay",()=>{var d=Ready();d.Version=8;Reject(d.Validate);});
        test("copy retains borrowing action without sharing mutable lists",()=>{var d=Ready();var copy=d.Copy();copy.Transactions[0]=copy.Transactions[0] with{Allocations=[new(Pocket.Id,500_000,Id)]};Equal(SelfDebtAction.Borrow,d.Transactions.Single().Allocations!.Single().DebtAction);Equal(500_000m,d.DebtAmounts(Id).Borrowed);});
        var folder=Path.Combine(Path.GetTempPath(),"MyPiggyBank-Borrow-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
        try{
            test("borrowing action and source bank survive manual Save Open",()=>{var file=Path.Combine(folder,"borrow.mpb");var session=new DocumentSession();session.Apply(Partial());session.Save(file);var bytes=File.ReadAllBytes(file);session.Apply(DebtService.EditDetails(session.Document,Id,"Renamed","",null));Equal(true,bytes.SequenceEqual(File.ReadAllBytes(file)));session.Save(file);var again=new DocumentSession();again.Open(file);Equal(9,again.Document.Version);Equal(new DebtTotals(500_000,200_000),again.Document.DebtAmounts(Id));Equal<Guid?>(Ocbc.Id,again.Document.Debts.Single().SelfBankId);Equal(SelfDebtAction.Borrow,again.Document.Transactions.First().Allocations!.Single().DebtAction);});
            test("format eight existing repayments migrate without reinterpretation or source rewrite",()=>{var file=Path.Combine(folder,"eight.mpb");var d=SelfDebtChecks.Fixture();d.Version=8;var ids=d.Debts.Select(x=>x.Id).ToList();var totals=ids.Select(id=>d.DebtAmounts(id)).ToList();var node=System.Text.Json.Nodes.JsonNode.Parse(JsonSerializer.Serialize(d))!;foreach(var tx in node["Transactions"]!.AsArray())if(tx!["Allocations"] is System.Text.Json.Nodes.JsonArray allocations)foreach(var a in allocations)a!.AsObject().Remove("DebtAction");File.WriteAllText(file,node.ToJsonString());var bytes=File.ReadAllBytes(file);var session=new DocumentSession();session.Open(file);Equal(9,session.Document.Version);Equal(true,totals.SequenceEqual(ids.Select(id=>session.Document.DebtAmounts(id))));Equal(true,bytes.SequenceEqual(File.ReadAllBytes(file)));Equal(false,session.Dirty);Equal(true,session.Document.Transactions.SelectMany(t=>t.Allocations??[]).All(a=>a.DebtAction==SelfDebtAction.Repay));});
        }finally{Directory.Delete(folder,true);}
    }
}
